        // 三平面取樣:垂直崖面不會把 XZ 花紋沿 Y 整條拉直，投影換手也沒有可見接縫。
        float celTriNoise( vec3 p, vec3 wn ) {
          vec3 w = pow( abs( wn ), vec3( 4.0 ) );
          w /= max( 1e-5, w.x + w.y + w.z );
          return celNoise( p.yz ) * w.x + celNoise( p.xz ) * w.y + celNoise( p.xy ) * w.z;
